with filtered as (select *, date_format(event_time, 'MMM yyyy') as event_time_label from web_events where to_date(event_time) < '2025-04-21'), flagged as (select *, case when lag(event_time) over (partition by page order by event_time, id) is null or event_time > lag(event_time) over (partition by page order by event_time, id) + interval 30 days then 1 else 0 end as is_new_burst from filtered), sessions_web_events as (select *, sum(is_new_burst) over (partition by page order by event_time, id rows between unbounded preceding and current row) as island_id from flagged) select case when duration_sec >= 465 then 'LARGE' else 'SMALL' end as duration_sec_tier, case when island_id >= 9 then 'HIGH' else 'LOW' end as island_id_tier, sum(case when page = '/cart' then is_new_burst else 0 end) as cart_is_new_burst, count(case when page = '/product' then 1 end) as product_count, max(event_time) as last_seen, count(case when page = '/product' then 1 end) as product_count_2, round(sum(duration_sec) / nullif(count(case when page = '/product' then 1 end), 0), 2) as duration_sec_per_product, count(case when event_type = 'search' then 1 end) as search_count from sessions_web_events group by grouping sets ((case when duration_sec >= 465 then 'LARGE' else 'SMALL' end, case when island_id >= 9 then 'HIGH' else 'LOW' end), (case when duration_sec >= 465 then 'LARGE' else 'SMALL' end)) order by duration_sec_per_product desc nulls last;
